import re
from auto_config.generator.enb.enb import ENB
from auto_config.generator.vcu.vcu import VCU
from auto_config.generator.gnb.gnb import GNB


class BTSFactory:

    def __init__(self, for_n1=False):
        self._for_n1 = for_n1

    def bts_key_to_class(self, bts_key):
        match = re.match(r'enb(\d+)|vcu(\d+)|gnb(\d+)$', bts_key, re.IGNORECASE)
        if match:
            if match.group(1) is not None:
                return ENB
            elif match.group(2) is not None:
                return VCU
            else:
                return GNB
        raise Exception("Unsupported BTS key: {bts_key}")

    def to_file(
        self, output_dir, execution_config,
        ue_config, enb_config, env_config, epc_config,
        hw_config,
        # pddb_topology,
        pddb_release,
        pddb_parser
    ):
        enb_configs_by_class = {}
        for bts_key, bts_ent_config in sorted(enb_config.items()):
            bts_class = self.bts_key_to_class(bts_key)
            if bts_class in enb_configs_by_class:
                enb_configs_by_class[bts_class][bts_key] = bts_ent_config
                continue
            enb_configs_by_class[bts_class] = {bts_key: bts_ent_config}

        for bts_class in enb_configs_by_class:
            bts_class(for_n1=self._for_n1).to_file(
                output_dir=output_dir,
                execution_config=execution_config,
                ue_config=ue_config,
                enb_config=enb_configs_by_class[bts_class],
                env_config=env_config,
                epc_config=epc_config,
                hw_config=hw_config,
                pddb_release=pddb_release,
                pddb_parser=pddb_parser,
            )
